insert into public.product_catalog as pc(variant_id,product_id,canonical_slug,sku,product_name,product_status,active,color,size,currency,unit_price,compare_at_price,availability_state,inventory_tracking,inventory_quantity,variant_data) select variant_id,product_id,canonical_slug,sku,product_name,product_status,active,color,size,currency,unit_price,compare_at_price,availability_state,inventory_tracking,inventory_quantity,variant_data from incoming_catalog on conflict(variant_id) do update set product_id=excluded.product_id,canonical_slug=excluded.canonical_slug,sku=excluded.sku,product_name=excluded.product_name,product_status=excluded.product_status,active=excluded.active,color=excluded.color,size=excluded.size,currency=excluded.currency,unit_price=excluded.unit_price,compare_at_price=excluded.compare_at_price,availability_state=excluded.availability_state,inventory_tracking=excluded.inventory_tracking,inventory_quantity=excluded.inventory_quantity,variant_data=excluded.variant_data,updated_at=now();
